import{_ as o,A as a,o as d,c as n,X as t,C as c}from"./chunks/framework.6lxT3esk.js";const g=JSON.parse('{"title":"Errors and crate-root exports","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/api/reference-errors.md","filePath":"reference-errors.md"}'),i={name:"rust/api/reference-errors.md"};function s(l,e,p,h,u,f){const r=a("DocChoices");return d(),n("div",null,[e[0]||(e[0]=t('<h1 id="errors-and-crate-root-exports" tabindex="-1">Errors and crate-root exports <a class="header-anchor" href="#errors-and-crate-root-exports" aria-label="Permalink to &quot;Errors and crate-root exports&quot;">​</a></h1><p>The crate has two error domains. Storage, codecs, metadata and runtime use <code>cellpack::Error</code> / <code>cellpack::Result&lt;T&gt;</code>. Loading and planning use <code>cellpack::loader::Error</code> / <code>loader::Result&lt;T&gt;</code>. The root also re-exports <code>CpkFile</code> and <code>CpkWriter</code> for convenience.</p>',2)),c(r,{title:"Start with the failing operation",items:[{label:"Read, write or decode",when:"A synchronous storage or codec call returned Err",href:"#format-codec-and-storage-errors",detail:"Inspect cellpack::Error. Failed output may be partial; correct the cause before reading again."},{label:"Prepare or execute a run",when:"A source, plan, worker or consumer failed",href:"#loader-and-planner-errors",detail:"Inspect loader::Error and distinguish rejected preparation from cancellation of an active run."}]}),e[1]||(e[1]=t('<p>This page explains what to report and what can be reused. For a working consumption pattern, see <a href="/CellPack/rust/docs/loading.html">loading and ownership</a>; for the exact validated/trusted boundary, see <a href="/CellPack/rust/docs/data-contracts.html">data contracts</a>.</p><h2 id="format-codec-and-storage-errors" tabindex="-1">Format, codec, and storage errors <a class="header-anchor" href="#format-codec-and-storage-errors" aria-label="Permalink to &quot;Format, codec, and storage errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variant</th><th>Meaning</th><th>Recovery scope</th></tr></thead><tbody><tr><td><code>InvalidInput / InvalidOptions</code></td><td>An argument or declaration violates the API</td><td>Correct inputs/options before retrying</td></tr><tr><td><code>OutputTooSmall { need, have }</code></td><td>Output extent differs from the required size</td><td>Use the operation&#39;s sizing contract; exact-size calls can also reject oversized buffers</td></tr><tr><td><code>WorkspaceTooSmall</code></td><td>Scratch is undersized</td><td>Allocate the requested number of <code>u64</code> words</td></tr><tr><td><code>OutputTypeTooNarrow</code></td><td>Index/offset type cannot hold a required value</td><td>Use a wider output integer type</td></tr><tr><td><code>RowOutOfRange</code></td><td>Requested row/cell/chunk position is invalid</td><td>Correct the selector and id space</td></tr><tr><td><code>TablesMismatch</code></td><td>Tables belong to different metadata</td><td>Rebuild/bind the correct tables</td></tr><tr><td><code>CorruptMeta / CorruptRecord</code></td><td>An explicitly checked consistency rule failed</td><td>Reject the affected input/output</td></tr><tr><td><code>Io</code></td><td>File operation failed</td><td>Inspect preserved error kind and message</td></tr></tbody></table><p>These errors do not imply every malformed record is checked. Trusted inner-record corruption can violate optimized decoder assumptions. After a failed read/decode, discard potentially partial output.</p><p><code>OutputTooSmall</code> sizes follow the particular operation&#39;s output unit; they are not universally byte counts. <code>WorkspaceTooSmall</code> always reports <code>u64</code> words. Use the <a href="/CellPack/rust/api/contracts.html#shapes-and-capacity">shape and capacity reference</a> rather than inferring allocation units from the variant name.</p><p><code>Error::Io { kind, message }</code> preserves the OS error kind and formatted message, not the original <code>std::io::Error</code> object. Match <code>kind</code> for programmatic decisions and retain <code>message</code> for diagnostics. <code>CorruptRecord</code> reports an explicit failed comparison; it is not evidence that decoding arbitrary damaged records is safe.</p><h2 id="loader-and-planner-errors" tabindex="-1">Loader and planner errors <a class="header-anchor" href="#loader-and-planner-errors" aria-label="Permalink to &quot;Loader and planner errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variant</th><th>Meaning</th><th>Recovery scope</th></tr></thead><tbody><tr><td><code>Config(String)</code></td><td>Invalid declaration or protocol use</td><td>Correct configuration or call order</td></tr><tr><td><code>Access { position, cell }</code></td><td>Sequence names a cell outside the source</td><td><code>position</code> is the access index <code>k</code>; check registration ranges and schema expansion</td></tr><tr><td><code>Io</code></td><td>OS I/O failure or short read</td><td>Inspect the OS error and input/storage state</td></tr><tr><td><code>CellPack</code></td><td>Wrapped format/codec/storage error</td><td>Preserve and inspect its underlying cause</td></tr><tr><td><code>Plan(String)</code></td><td>Incompatible plan, costs or planning options</td><td>Correct options or recompile for the actual graph</td></tr><tr><td><code>Process(status)</code></td><td>Native process callback failed</td><td>Interpret application-defined status</td></tr><tr><td><code>Accesses(status)</code></td><td>Native sampling callback failed</td><td>Interpret application-defined status</td></tr><tr><td><code>WorkerPanic</code></td><td>A worker or compiler thread panicked</td><td>Fail the run and inspect diagnostics</td></tr><tr><td><code>Busy</code></td><td>A loader/run or ring producer is already occupied</td><td>Finish the existing work and drop its run handle before retrying</td></tr><tr><td><code>Aborted</code></td><td>Cancellation was observed</td><td>Stop this run; identify its originating cause</td></tr></tbody></table><p>For <code>S</code> schemas, access index <code>k</code> belongs to logical position <code>k / S</code> and schema index <code>k % S</code>. The field name <code>position</code> in <code>Error::Access</code> does <strong>not</strong> refer to that logical position. A wrong cell may originate in a native sampler, a stored sequence, or an incorrect per-schema offset.</p><h3 id="preserve-the-cause" tabindex="-1">Preserve the cause <a class="header-anchor" href="#preserve-the-cause" aria-label="Permalink to &quot;Preserve the cause&quot;">​</a></h3><p><code>loader::Error::Io</code> retains its <code>std::io::Error</code>; <code>CellPack</code> retains the underlying <code>cellpack::Error</code>. Both participate in <code>std::error::Error::source()</code>. Report the operation context with the error chain, rather than replacing it with a generic &quot;loading failed&quot; message. Callback statuses are application-defined nonzero codes, not portable OS error numbers.</p><p>A producer or worker failure cancels other participants, which can then report <code>Aborted</code>. The producer joins its threads and prefers a non-<code>Aborted</code> cause over secondary cancellation. <code>for_each_batch</code> also preserves a consumer callback&#39;s error; if consumption only observed cancellation, it returns the producer&#39;s result instead. With several concurrent failures, this is not a guarantee of which failure happened first in wall-clock time.</p><h3 id="decide-what-to-reuse" tabindex="-1">Decide what to reuse <a class="header-anchor" href="#decide-what-to-reuse" aria-label="Permalink to &quot;Decide what to reuse&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure point</th><th>Meaning for the next attempt</th></tr></thead><tbody><tr><td>Source/schema/plan construction or rejected <code>prepare</code></td><td>Correct the declaration or file state. No successful prepared run was returned</td></tr><tr><td><code>Busy</code></td><td>Another owner is active; it is not a request to abort that owner&#39;s work</td></tr><tr><td><code>Config</code> saying the ring has ready/leased slots</td><td>Consume remaining ready output and release leases after successful production, or use a fresh ring</td></tr><tr><td>Failure during producer execution, or a <code>Run::wait</code> error</td><td>The run is cancelled; its ring is permanently aborted</td></tr><tr><td>Explicit <code>Run::cancel</code> or dropping a prepared but unstarted run</td><td>The ring is permanently aborted</td></tr><tr><td>Successful run</td><td>Drain output, release every lease, and drop the old run handle before reusing the loader and ring</td></tr></tbody></table><p>An aborted ring cannot be reset or prepared again. Allocate a fresh ring for a new attempt after fixing the originating cause. Keep old backing storage alive while any lease still references it, and discard incomplete output. A wrong-rank <code>wait</code> is a protocol error that cancels the run even though its variant is <code>Config</code>; the variant alone does not tell you whether a run remains usable.</p><p>If progress stops without an error, check <a href="/CellPack/rust/docs/troubleshooting.html#a-run-stops-making-progress">backpressure and held leases</a> before treating the wait as an I/O failure.</p><h2 id="root-interface-index" tabindex="-1">Root interface index <a class="header-anchor" href="#root-interface-index" aria-label="Permalink to &quot;Root interface index&quot;">​</a></h2><p>The crate root exports <code>Error</code>, <code>Result</code>, <code>CpkFile</code> and <code>CpkWriter</code>. Loading and planning use their own <code>loader::Result</code>, so qualify the result type when combining the two domains in one module. Other interfaces live in their named modules.</p><h3 id="re-exports" tabindex="-1">Re-exports <a class="header-anchor" href="#re-exports" aria-label="Permalink to &quot;Re-exports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-store-struct-CpkFile.html"><code>CpkFile</code></a></td><td>An opened .cpk file.</td></tr><tr><td><a href="/CellPack/rust/api/generated-store-struct-CpkWriter.html"><code>CpkWriter</code></a></td><td>Writes one matrix to a .cpk file. Rows are appended in order; the file is valid only after CpkWriter::finish .</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-root-enum-Error.html"><code>Error</code></a></td><td>Why an operation failed.</td></tr></tbody></table><h3 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to &quot;Type Aliases&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-root-type-Result.html"><code>Result</code></a></td><td>The crate’s result type.</td></tr></tbody></table>',24))])}const b=o(i,[["render",s]]);export{g as __pageData,b as default};
